import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"SourcePicker","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/source-picker.md","filePath":"workbench/source-picker.md"}'),d={name:"workbench/source-picker.md"};function c(i,e,s,h,n,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="sourcepicker" tabindex="-1">SourcePicker <a class="header-anchor" href="#sourcepicker" aria-label="Permalink to &quot;SourcePicker&quot;">​</a></h1><p>SourcePicker is the frame of a dialog that adds something from one of several places: the places on the left, the detail of the current one on the right.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it when something can come from more than one place, such as the files of the device, a library shared with the team or a link. The application passes the places, keeps the current one (<code>onpick</code> asks for another) and draws the detail of each place with the <code>detail</code> snippet, which receives the place. The action that adds what was chosen goes in <code>primary</code>. When files of the device are the only place, use a <a href="./../components/file-input">FileInput</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>false</code></td><td>Whether the dialog is open (bindable)</td></tr><tr><td><code>title</code></td><td>required</td><td>The title in the head, and the name of the places</td></tr><tr><td><code>sources</code></td><td>required</td><td>The places, <code>PickerSource[]</code></td></tr><tr><td><code>current</code></td><td></td><td>The id of the current place</td></tr><tr><td><code>onpick</code></td><td></td><td>Called with the id of the place that is pressed</td></tr><tr><td><code>detail</code></td><td>required</td><td>The detail of the current place (a snippet)</td></tr><tr><td><code>primary</code></td><td></td><td>The action that adds what was chosen (a snippet)</td></tr><tr><td><code>onclose</code></td><td></td><td>Called once when the dialog closes</td></tr><tr><td><code>inline</code></td><td><code>false</code></td><td>The same surface in the flow of a page</td></tr></tbody></table><p>A <code>PickerSource</code> is <code>{ id, label, description?, icon? }</code>.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A <a href="./../components/modal">Modal</a> of the widest size (<code>xl</code>) whose body reaches its edges. A <a href="./../components/split">Split</a> holds the places, a <a href="./../components/list">List</a> in a navigation landmark, on the left, and the detail in a <a href="./../components/block">Block</a> on the right. Each place is a pressable <a href="./../components/list-item">ListItem</a> with its icon, its name and its description; the current one is selected. Below 48rem the modal fills the screen and the places become <a href="./../components/tabs">Tabs</a> above the detail. The <a href="./../components/footer">Footer</a> holds a close button and <code>primary</code>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/source-picker/" title="SourcePicker" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/source-picker/" target="_blank" rel="noopener">SourcePicker</a></figcaption></figure>',11)])])}const u=t(d,[["render",c]]);export{f as __pageData,u as default};
